def odunc_ver(self, kitap_id, uye_id, tarih):
    """Kitabı üyeye verir. Kitap/üye yoksa, kitap ödünçteyse veya
    üyenin ödünç sınırına ulaştıysa ValueError."""
    if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
        raise ValueError("kitap ya da üye bulunamadı")
    if self._aktif(kitap_id):
        raise ValueError("kitap zaten ödünçte")
    uye = self.uyeler[uye_id]
    limit = self.SINIR.get(uye.tur, self.SINIR["standart"])
    aktif = len(self.oduncteki_kitaplar(uye_id))
    if aktif >= limit:
        raise ValueError(f"ödünç sınırına ulaşıldı (en fazla {limit})")
    kayit = Odunc(kitap_id, uye_id, tarih)
    self.kayitlar.append(kayit)
    return kayit

@staticmethod
def ceza_hesapla(alinma, iade, uye_tur="standart"):
    """Gecikme cezasını hesaplar: 14 gün serbest süre; aşan her gün gecikme.
    İlk 7 gecikme günü 2,50 TL/gün, sonraki günler 5,00 TL/gün; en fazla 150 TL.
    "ogrenci" üyelerde sınırdan sonra %50 indirim. Sonuç 2 ondalığa yuvarlanır."""
    gun = (iade - alinma).days
    gecikme = gun - ODUNC_SUresi_GUN
    if gecikme <= 0:
        return 0.0
    ceza = (
        min(gecikme, 7) * ILK_7_GUN_GUNLUK
        + max(gecikme - 7, 0) * SONRAKI_GUNLUK
    )
    ceza = min(ceza, CEZA_SINIRI)
    if uye_tur == "ogrenci":
        ceza *= OGRENCI_INDIRIM
    return round(ceza, 2)

def iade_al(self, kitap_id, tarih):
    """Kitabın iadesini alır, gecikme varsa cezayı hesaplayıp kayda yazar
    ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
    kayit = self._aktif(kitap_id)
    if kayit is None:
        raise ValueError("kitap ödünçte değil")
    uye = self.uyeler.get(kayit.uye_id)
    uye_tur = uye.tur if uye is not None else "standart"
    kayit.iade = tarih
    kayit.ceza = self.ceza_hesapla(kayit.alinma, tarih, uye_tur)
    return kayit

def toplam_ceza(self, uye_id) -> float:
    """Üyenin iade edilmiş tüm ödünçlerinin ceza toplamı."""
    return round(
        sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None),
        2,
    )

